using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class AEWeather {
 const string E="Assets/Afrer_Seconds/05.Model/Environment/1F/";static string O=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../Docs/Review/2026-11-12_1F_Abandoned/"));
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_1F_Factory.unity"))throw new Exception("Saved 1F required");AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);foreach(string n in new[]{"AE_BrickDetail_Albedo","AE_BrickDetail_Normal","AE_Grain_Albedo","AE_Grain_Normal"}){var ti=(TextureImporter)AssetImporter.GetAtPath(E+"Textures/"+n+".png");ti.maxTextureSize=n.Contains("Brick")?1024:512;ti.mipmapEnabled=true;ti.anisoLevel=4;ti.isReadable=false;ti.textureCompression=TextureImporterCompression.CompressedHQ;ti.sRGBTexture=!n.EndsWith("Normal");if(n.EndsWith("Normal"))ti.textureType=TextureImporterType.NormalMap;ti.SaveAndReimport();}
  var shader=AssetDatabase.LoadAssetAtPath<Shader>(E+"AEWeatheredLit.shader");if(!shader)throw new Exception("Shader missing");var changed=new List<string>();foreach(string n in new[]{"Plaster","Corrosion","Coat","Green","Steel","Rust","Red","Hazard","Concrete","Floor"}){var m=AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/AE_M_"+n+".mat");if(!m)throw new Exception("Material missing "+n);m.shader=shader;int mode=n=="Plaster"?1:n=="Concrete"||n=="Floor"?3:2;string tex=mode==1?"BrickDetail":"Grain";m.SetFloat("_AE_Mode",mode);m.SetFloat("_AE_MacroScale",mode==1?.28f:mode==2?.56f:.18f);m.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(E+"Textures/AE_"+tex+"_Albedo.png"));m.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>(E+"Textures/AE_"+tex+"_Normal.png"));m.SetTexture("_MetallicGlossMap",null);m.DisableKeyword("_METALLICSPECGLOSSMAP");m.EnableKeyword("_NORMALMAP");m.SetFloat("_BumpScale",mode==1?.7f:.45f);m.SetTextureScale("_BaseMap",Vector2.one);if(mode!=2)m.SetColor("_BaseColor",Color.white);m.DisableKeyword("_EMISSION");m.SetColor("_EmissionColor",Color.black);EditorUtility.SetDirty(m);changed.Add(m.name);}
  AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);var renderers=GameObject.Find("1F_AbandonedFactory").GetComponentsInChildren<Renderer>().Where(rr=>rr.sharedMaterials.Any(m=>m&&m.shader==shader)).ToArray();var messages=ShaderUtil.GetShaderMessages(shader).Select(m=>new{m.message,severity=m.severity.ToString(),m.file,m.line}).ToArray();var result=new{shader=shader.name,supported=shader.isSupported,materials=changed,renderers=renderers.Length,messages,brickUVScaleUnchanged=true,worldSpaceWear=true,geometryModified=false};File.WriteAllText(O+"weathering.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;
 }
 public static object Check(){var shader=AssetDatabase.LoadAssetAtPath<Shader>(E+"AEWeatheredLit.shader");var messages=ShaderUtil.GetShaderMessages(shader).Select(m=>new{m.message,severity=m.severity.ToString(),m.file,m.line}).ToArray();var result=new{supported=shader.isSupported,messages,errors=messages.Count(m=>m.severity=="Error")};File.WriteAllText(O+"shader_validation.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
